import React, { useState } from 'react';

/**
 * Image simple avec un fallback propre.
 * Si un fichier manque, le site continue de compiler et garde le fond prévu par le CSS.
 */
export default function MediaImage({ src, alt = '', className = '' }) {
  const [failed, setFailed] = useState(false);

  if (!src || failed) return null;

  return (
    <img
      className={className}
      src={src}
      alt={alt}
      loading="lazy"
      decoding="async"
      onError={() => setFailed(true)}
    />
  );
}
